import{c as a,Q as t,j as i,m as s}from"./chunks/framework.W-g_WCNV.js";const k=JSON.parse('{"title":"Admin API key","description":"Authenticate server-side API requests to GateKeeper using a personal API key.","frontmatter":{"title":"Admin API key","description":"Authenticate server-side API requests to GateKeeper using a personal API key."},"headers":[],"relativePath":"admin/api-key.md","filePath":"admin/api-key.md"}'),n={name:"admin/api-key.md"};function o(r,e,l,h,d,p){return t(),i("div",null,[...e[0]||(e[0]=[s(`<p>Each admin account can generate a personal API key. The key lets server-side services call GateKeeper&#39;s admin API without a browser session - useful for dashboards, monitoring scripts, or any tool that needs to read GateKeeper data programmatically.</p><h2 id="generating-a-key" tabindex="-1">Generating a key <a class="header-anchor" href="#generating-a-key" aria-label="Permalink to &quot;Generating a key&quot;">​</a></h2><p>Go to <strong>My account</strong> (<code>/profile</code>) and scroll to the <strong>API key</strong> card. Click <strong>Generate key</strong>. The key is displayed once - copy it now. Click the eye icon to reveal it, then use the copy button.</p><h2 id="rotating-the-key" tabindex="-1">Rotating the key <a class="header-anchor" href="#rotating-the-key" aria-label="Permalink to &quot;Rotating the key&quot;">​</a></h2><p>Click <strong>Rotate key</strong> on the same card. You will be asked to confirm before the old key is invalidated. The new key is shown immediately after rotation.</p><p>Store only one key at a time. There is no way to retrieve the current key after leaving the page, but you can always rotate and copy the new value.</p><h2 id="using-the-key" tabindex="-1">Using the key <a class="header-anchor" href="#using-the-key" aria-label="Permalink to &quot;Using the key&quot;">​</a></h2><p>Send the key in the <code>X-Api-Key</code> request header:</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /admin/users </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">HTTP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Host</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auth.example.com</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">X-Api-Key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your-api-key-here</span></span></code></pre></div><p>The key is accepted on all admin API endpoints in place of a session cookie. Session-based access (browser login) continues to work alongside key-based access.</p><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><ul><li>The key is stored in the database alongside your admin account. Rotating it immediately invalidates the previous value.</li><li>Use the key only in server-side code. Do not expose it in client-side JavaScript or commit it to version control.</li><li>Treat it like a password: use a secrets manager or environment variable to pass it to the services that need it.</li></ul>`,12)])])}const y=a(n,[["render",o]]);export{k as __pageData,y as default};
